import { getAppUrl } from './appUrl';

/**
 * Badge ID -> pinned IPFS metadata URI.
 *
 * Originally generated by the badge upload script. Only add entries here once the CID is
 * real and pinned — a bad CID produces an NFT whose metadata never resolves, and NFT
 * metadata cannot be edited after minting.
 *
 * Badges without an entry fall back to /api/metadata/badge?id=<id>, which is served by
 * this app and always resolves.
 */
export const BADGE_TOKEN_URIS: Record<string, string> = {
  'first-game': 'ipfs://bafkreiczx6oerb3bnjetzgr2bwgziuuoa373gpglesvxp23dmulm7ndnwi',
  'five-games': 'ipfs://bafkreiekkewdloapyri4nrqllr4hkitpgm2h5gylro4fxsaa3tfkfofaia',
  'ten-games': 'ipfs://bafkreidk5dqbpjvoobpjl4fktsqaync7t22un4o4qik4djytklscrygot4',
  'twenty-five-games': 'ipfs://bafkreihagsq23wum6bf6s4ma2rvk5rmcwgthcarqv2lcikhtjpzqibgvai',
  'fifty-games': 'ipfs://bafkreih5mgafq3weriokfuicjryt53nmdsrcy57j7yr4q2r22lovvnzhwy',
  'xp-100': 'ipfs://bafkreigft4h5b2jak253xtcsb4aa5j4rtuvrlwyptd3cclob6ci4qison4',
  'xp-500': 'ipfs://bafkreignzjhb44q5zfuyi5wpcduw423vpnbv5jimt3ih2ilea244dzsdtq',
  'xp-1000': 'ipfs://bafkreiesoagexy77vtlucddtoih7gxdkb3mtwjk6ic4lrw3xmnrqvharum',
  'flappy-10': 'ipfs://bafkreigp4gse3gvp4mmtjhmb2swytack2qu6z43l4dmou6iiotismrirsu',
  'flappy-50': 'ipfs://bafkreidqqnei2kiqvos5gozemuoqoyu3gioc6oyvu42hwyjzgflmizasty',
  'all-rounder': 'ipfs://bafkreie5qsh64q3rkcn26smu6e3e6xemht3xt5avn4fq23cvqejwcu4jyy',
  // NOTE: sudoku-500 / sudoku-1500 previously held placeholder CIDs that did not exist.
  // They now resolve through /api/metadata/badge until real CIDs are pinned.
};

/**
 * Maximum metadata URI length accepted by the ginix_nfts program:
 *   require!(metadata_uri.len() <= 200, NftError::UriTooLong)
 * Metaplex itself also caps the on-chain uri field at 200 bytes.
 */
export const MAX_METADATA_URI_LEN = 200;

/**
 * Resolve the metadata URI for a badge NFT.
 *
 * Returns a pinned IPFS URI when available, otherwise a short HTTPS URL served by this
 * app. Never returns a `data:` URI — those exceed the on-chain 200-byte limit and would
 * make every mint fail.
 */
export function getBadgeTokenURI(badgeId: string): string {
  const uri = BADGE_TOKEN_URIS[badgeId] || `${getAppUrl()}/api/metadata/badge?id=${encodeURIComponent(badgeId)}`;

  if (Buffer.byteLength(uri, 'utf8') > MAX_METADATA_URI_LEN) {
    throw new Error(
      `Metadata URI for badge "${badgeId}" is ${Buffer.byteLength(uri, 'utf8')} bytes, exceeding the ${MAX_METADATA_URI_LEN}-byte on-chain limit`
    );
  }

  return uri;
}

/**
 * Resolve the metadata URI for a high-score NFT.
 */
export function getScoreTokenURI(gameId: string, score: number): string {
  const uri = `${getAppUrl()}/api/metadata/score?g=${encodeURIComponent(gameId)}&s=${score}`;

  if (Buffer.byteLength(uri, 'utf8') > MAX_METADATA_URI_LEN) {
    throw new Error(
      `Metadata URI for score NFT (${gameId}, ${score}) is ${Buffer.byteLength(uri, 'utf8')} bytes, exceeding the ${MAX_METADATA_URI_LEN}-byte on-chain limit`
    );
  }

  return uri;
}
